<script setup lang="ts">
/**
 * Radio or checkbox options as cards with room for a description (`design/components/choice-card.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/choice-card.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef } from 'vue'

import { Icon, agentMember, roveRadio, type IconRole } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/choice-card.module.css'

export interface ChoiceCardOption {
  value: string
  label: string
  description?: string
  icon?: IconRole
  disabled?: boolean
}

export interface ChoiceCardProps {
  /**
   * The maximum column count. The container resolves the actual count on Grid's scale
   * (`grid.md`).
   */
  columns?: 1 | 2 | 3
  defaultValue?: string | string[]
  disabled?: boolean
  /**
   * The group's accessible name (`aria-label` on the root).
   */
  label: string
  mode: 'single' | 'multiple'
  /**
   * Items render from data (Radio's law).
   */
  options: ChoiceCardOption[]
  value?: string | string[]
}

defineOptions({ name: 'ChoiceCard', inheritAttrs: false })

const props = withDefaults(defineProps<ChoiceCardProps>(), { columns: 1, disabled: false })
const emit = defineEmits<{ change: [values: string | string[]] }>()
const uid = useId()
const singleMirror = ref(
  props.mode === 'single' ? (props.defaultValue as string | undefined) : undefined,
)
const multipleMirror = ref(
  props.mode === 'multiple' ? ((props.defaultValue as string[] | undefined) ?? []) : [],
)
const grid = useTemplateRef<HTMLElement>('grid')
const chosen = computed(() =>
  props.mode === 'single' ? ((props.value as string | undefined) ?? singleMirror.value) : undefined,
)
const checkedValues = computed(() =>
  props.mode === 'multiple'
    ? ((props.value as string[] | undefined) ?? multipleMirror.value)
    : ([] as string[]),
)
const isChecked = computed(
  () => (optionValue: string) =>
    props.mode === 'single'
      ? chosen.value === optionValue
      : checkedValues.value.includes(optionValue),
)
const stop = computed(
  () =>
    chosen.value ??
    props.options.find((option) => !(props.disabled || option.disabled === true))?.value,
)
const select = computed(
  () => (next: string) =>
    next !== chosen.value && ((singleMirror.value = next), emit('change', next), true),
)
const toggle = computed(
  () => (optionValue: string, checked: boolean) =>
    ((next: string[]) => ((multipleMirror.value = next), emit('change', next)))(
      props.options
        .filter((option) =>
          option.value === optionValue ? checked : checkedValues.value.includes(option.value),
        )
        .map((option) => option.value),
    ),
)
const chooseAll = computed(
  () => (chosen: readonly string[]) =>
    ((next: string[]) =>
      next.length === checkedValues.value.length &&
      next.every((each) => checkedValues.value.includes(each))
        ? undefined
        : ((multipleMirror.value = next), emit('change', next)))(
      props.options
        .filter((option) =>
          props.disabled || option.disabled === true
            ? checkedValues.value.includes(option.value)
            : chosen.includes(option.value),
        )
        .map((option) => option.value),
    ),
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'ChoiceCard',
    element: () => grid.value,
    state: () => ({
      value:
        props.mode === 'single'
          ? chosen.value === undefined
            ? []
            : [chosen.value]
          : checkedValues.value,
      options: props.options.map((option) => ({
        id: option.value,
        label: option.label,
        ...(option.disabled === true ? { disabled: true } : {}),
      })),
      mode: props.mode,
      disabled: props.disabled,
    }),
    actions: {
      choose: {
        argument: 'ids',
        run: (value) =>
          (() => {
            if (props.mode === 'multiple') return chooseAll.value(value)
            const [only] = value
            if (only === undefined || value.length !== 1)
              throw new Error('A single-choice ChoiceCard takes exactly one id.')
            select.value(only)
          })(),
      },
    },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <div
    v-if="mode === 'single'"
    ref="grid"
    :class="styles.grid"
    role="radiogroup"
    :aria-label="label"
    :data-columns="String(columns)"
    :data-disabled="disabled ? '' : undefined"
    data-member="choice-card"
  >
    <template v-for="(option, index) in options" :key="option.value">
      <!-- option -->
      <label
        :class="styles.option"
        :data-state="isChecked(option.value) ? 'checked' : 'unchecked'"
        :data-disabled="disabled || option.disabled === true ? '' : undefined"
      >
        <!-- card -->
        <button
          :class="styles.control"
          type="button"
          role="radio"
          :value="option.value"
          :aria-checked="isChecked(option.value)"
          :disabled="disabled || option.disabled === true"
          :aria-labelledby="`${uid}-option-${index}-label`"
          :aria-describedby="
            option.description !== undefined ? `${uid}-option-${index}-description` : undefined
          "
          :data-state="isChecked(option.value) ? 'checked' : 'unchecked'"
          :data-disabled="disabled || option.disabled === true ? '' : undefined"
          :tabindex="option.value === stop ? 0 : -1"
          @click="select(option.value)"
          @keydown="
            $event.key === 'Enter'
              ? $event.preventDefault()
              : roveRadio($event, (next) => select(next))
          "
        />
        <span v-if="option.icon !== undefined" :class="styles.icon">
          <Icon :name="option.icon" size="md" />
        </span>
        <span :class="styles.label" :id="`${uid}-option-${index}-label`">
          {{ option.label }}
        </span>
        <span
          v-if="option.description !== undefined"
          :class="styles.description"
          :id="`${uid}-option-${index}-description`"
        >
          {{ option.description }}
        </span>
        <span v-if="isChecked(option.value)" :class="styles.glyph">
          <Icon name="confirm" size="md" />
        </span>
      </label>
    </template>
  </div>
  <div
    v-else
    ref="grid"
    :class="styles.grid"
    role="group"
    :aria-label="label"
    :data-columns="String(columns)"
    :data-disabled="disabled ? '' : undefined"
    data-member="choice-card"
  >
    <template v-for="(option, index) in options" :key="option.value">
      <!-- option -->
      <label
        :class="styles.option"
        :data-state="isChecked(option.value) ? 'checked' : 'unchecked'"
        :data-disabled="disabled || option.disabled === true ? '' : undefined"
      >
        <!-- card -->
        <button
          :class="styles.control"
          type="button"
          role="checkbox"
          :value="option.value"
          :aria-checked="isChecked(option.value)"
          :disabled="disabled || option.disabled === true"
          :aria-labelledby="`${uid}-option-${index}-label`"
          :aria-describedby="
            option.description !== undefined ? `${uid}-option-${index}-description` : undefined
          "
          :data-state="isChecked(option.value) ? 'checked' : 'unchecked'"
          :data-disabled="disabled || option.disabled === true ? '' : undefined"
          @click="toggle(option.value, !isChecked(option.value))"
          @keydown="$event.key === 'Enter' && $event.preventDefault()"
        />
        <span v-if="option.icon !== undefined" :class="styles.icon">
          <Icon :name="option.icon" size="md" />
        </span>
        <span :class="styles.label" :id="`${uid}-option-${index}-label`">
          {{ option.label }}
        </span>
        <span
          v-if="option.description !== undefined"
          :class="styles.description"
          :id="`${uid}-option-${index}-description`"
        >
          {{ option.description }}
        </span>
        <span v-if="isChecked(option.value)" :class="styles.glyph">
          <Icon name="confirm" size="md" />
        </span>
      </label>
    </template>
  </div>
</template>
